let manifest_path = root.join("iterations.json");
let mut manifest: serde_json::Value =
    serde_json::from_str(&fs::read_to_string(&manifest_path).unwrap()).unwrap();
manifest["iterations"] = serde_json::Value::Array(vec![]);
manifest["active_iteration"] = serde_json::Value::Null;
manifest["stop_reason"] = serde_json::Value::String("interrupted".into());
manifest["interrupted_iteration"] = serde_json::json!({
    "directory": "iteration-01",
    "task_requests": 0,
    "wire_requests": 0
});
